cmd = r'''python3 - << 'PY'
import re
src=open("crates/mm-engine/src/builtins.rs").read()
# function spans
fns=[]
for m in re.finditer(r"\n(?:pub(?:\(crate\))? )?fn ([A-Za-z0-9_]+)\(", src):
    fns.append((m.start(), m.group(1)))
fns.append((len(src), "END"))
# also impl methods
impls=[]
for m in re.finditer(r"\n    (?:pub\(crate\) )?fn ([A-Za-z0-9_]+)\(", src):
    impls.append((m.start(), m.group(1)))

def owner(pos):
    name="?"
    for i,(p,n) in enumerate(fns):
        if p<=pos<fns[i+1][0]:
            return n
    # maybe method
    best=None
    for p,n in impls:
        if p<=pos and (best is None or p>best[0]):
            best=(p,n)
    return best[1] if best else "?"

hits=[]
for m in re.finditer(r"prelude_request\(\s*\"([^\"]+)\"|self\.request = Some\(Request::|vm\.request = Some\(Request::|need_py\(", src):
    line=src[:m.start()].count("\n")+1
    fn=owner(m.start())
    hits.append((line, fn, m.group(0)[:80]))

print("HITS", len(hits))
from collections import defaultdict
d=defaultdict(list)
for line,fn,txt in hits:
    d[fn].append(f"L{line}:{txt}")
for fn,xs in d.items():
    print(f"\n{fn}")
    for x in xs:
        print(" ", x)
PY'''
