cmd = r'''python3 - << 'PY'
import re, os
from collections import defaultdict, deque
root="crates/mm-engine/src"
files=[]
for dp,_,fns in os.walk(root):
    for fn in fns:
        if fn.endswith('.rs'):
            files.append(os.path.join(dp,fn))
# unique id per function
items=[]  # id, file, name, body
for f in files:
    src=open(f).read(); n=len(src); i=0
    while True:
        m=re.search(r"\n[ \t]*(?:pub(?:\(crate\))? )?(?:async )?fn ([A-Za-z0-9_]+)\s*(?:<[^(){};]*?>)?\s*\(", src[i:])
        if not m: break
        name=m.group(1); j=i+m.end(); depth_p=1
        while j<n and depth_p:
            c=src[j]
            if c=='(': depth_p+=1
            elif c==')': depth_p-=1
            elif c=='"':
                j+=1
                while j<n and src[j]!='"':
                    j+=2 if src[j]=='\\' else 1
            j+=1
        while j<n and src[j]!='{':
            j+=1
        if j>=n: break
        depth=0; k=j
        while k<n:
            c=src[k]
            if c=='{': depth+=1
            elif c=='}':
                depth-=1
                if depth==0:
                    k+=1; break
            elif c=='"':
                k+=1
                while k<n and src[k]!='"':
                    k+=2 if src[k]=='\\' else 1
            elif c=="'":
                k+=1
                while k<n and src[k]!="'":
                    k+=2 if src[k]=='\\' else 1
            elif src.startswith('//', k):
                while k<n and src[k]!='\n': k+=1
            k+=1
        items.append([os.path.relpath(f, root), name, src[j:k]])
        i=k if k>i else i+1

MARK=re.compile(r"need_py\(|prelude_request\(|\bdunder_call\(|\bcall_request\(|Request::Call|Request::Throw|Request::Run")
SKIP={"collect_garbage","dispatch_rare","land","drive","finish","next_request","wrap_request","prelude_request","hand_to_twin","call_native","op_slow"}
# index methods by name
byname=defaultdict(list)
for idx,(f,name,body) in enumerate(items):
    byname[name].append(idx)

def calls_of(idx):
    f,name,body=items[idx]
    out=set()
    for m in re.finditer(r"(?:self|vm)\.([A-Za-z0-9_]+)\s*\(", body):
        for j in byname.get(m.group(1), []):
            # prefer same file
            out.add(j)
    # free functions in same file
    for m in re.finditer(r"(?<![\w:.])([A-Za-z_][A-Za-z0-9_]*)\s*\(", body):
        nm=m.group(1)
        for j in byname.get(nm, []):
            if items[j][0]==f and j!=idx:
                out.add(j)
    return out

seeds=set()
for idx,(f,name,body) in enumerate(items):
    if name in SKIP: continue
    if MARK.search(body):
        seeds.add(idx)

# reverse BFS distance to nearest seed
dist={s:0 for s in seeds}
parent={s:None for s in seeds}
# build callers
callers=defaultdict(set)
for idx in range(len(items)):
    for c in calls_of(idx):
        callers[c].add(idx)
q=deque(seeds)
while q:
    n=q.popleft()
    for c in callers.get(n,()):
        if c not in dist and items[c][1] not in SKIP:
            dist[c]=dist[n]+1
            parent[c]=n
            q.append(c)

def path(idx):
    p=[]
    while idx is not None:
        f,name,_=items[idx]
        p.append(f"{name}@{f}")
        idx=parent.get(idx)
        if len(p)>12: break
    return " <- ".join(p)

# DEFS
src=open('crates/mm-engine/src/builtins.rs').read()
m=re.search(r"const DEFS: &\[Def\] = &\[", src)
body=src[m.end():]; body=body[:body.find('\n];')]
body=re.sub(r'//[^\n]*','',body)
entries=[]
i=0
while True:
    j=re.search(r'(n!|m!|p!)\(', body[i:])
    if not j: break
    start=i+j.start(); k=i+j.end()-1; depth=0
    while k<len(body):
        c=body[k]
        if c=='(': depth+=1
        elif c==')':
            depth-=1
            if depth==0:
                k+=1; break
        k+=1
    text=body[start:k]; kind=j.group(1)[0]
    strs=re.findall(r'"((?:\\.|[^"\\])*)"', text)
    fnm=re.search(r',\s*([A-Za-z0-9_:]+)\s*\)\s*$', text)
    fn=fnm.group(1) if fnm else '?'
    short=fn.split('::')[-1]
    mod=None
    if '::' in fn:
        mod=fn.split('::')[1] if fn.count('::')==2 else fn.split('::')[0]
        # crate::bytes::fromhex -> bytes.rs
    if kind=='n':
        own=re.search(r'"[^"]*"\s*,\s*([^,\n]+)', text, re.S).group(1).strip()
        label = strs[0] if own=='None' else f'{own}.{strs[0]}'
    elif kind=='m':
        label=f'{strs[0]}.{strs[1]}'
    else:
        label=f'_prelude.{strs[0]}'
    # find impl indices: if path given, match file stem
    cands=byname.get(short, [])
    if '::' in fn:
        stem=fn.split('::')[-2]
        cands2=[c for c in cands if stem in items[c][0]]
        if cands2: cands=cands2
    elif short.startswith('bi_') or short.startswith('pl_') or short.startswith('aio_') or short.startswith('gen_') or short.startswith('coro_') or short in ('to_module_twin','slot_getitem','list_sort','min_max'):
        cands2=[c for c in cands if items[c][0]=='builtins.rs']
        if cands2: cands=cands2
    best=None
    for c in cands:
        if c in dist and (best is None or dist[c]<dist[best]):
            best=c
    entries.append((label, fn, best, dist.get(best) if best is not None else None))
    i=k

yes=[e for e in entries if e[3] is not None]
no=[e for e in entries if e[3] is None]
print('YES', len(yes), 'NO', len(no), 'fns', len(items), 'seeds', len(seeds), 'reached', len(dist))
# group yes by distance
from collections import Counter
print('dist', Counter(e[3] for e in yes))
print('\n== distance 0 (direct) ==')
for e in yes:
    if e[3]==0:
        print(f'{e[0]}  {e[1]}')
print('\n== distance >0 unique paths sample ==')
shown=set()
for e in sorted(yes, key=lambda e: (e[3], e[0])):
    if e[3]==0: continue
    key=(e[1], e[3])
    if key in shown: 
        continue
    shown.add(key)
    print(f'{e[3]} {e[0]} :: {path(e[2])}')
PY'''
