code = r'''python3 - << 'END'
import math, struct, random

MOD = (1<<61)-1

def frexp_rs(x):
    bits = struct.unpack('>Q', struct.pack('>d', x))[0]
    exp = (bits >> 52) & 0x7FF
    if exp == 0:
        m,e = frexp_rs(x * struct.unpack('>d', struct.pack('>Q', 0x4350000000000000))[0])
        return m, e-54
    mbits = (bits & ~(0x7FF << 52)) | (1022 << 52)
    m = struct.unpack('>d', struct.pack('>Q', mbits))[0]
    return m, exp - 1022

def hash_float(v):
    if math.isnan(v):
        return 0
    if math.isinf(v):
        return 314159 if v>0 else -314159
    if v == 0.0:
        return 0
    m,e = frexp_rs(v)
    sign = 1
    if m < 0:
        sign = -1
        m = -m
    x = 0
