    m = __import__('struct').unpack('<d', mant.to_bytes(8,'little'))[0]
    return m, exp - 1022

def hash_float(v):
    if v != v:
        return 0
    if v == float('inf'):
        return 314159
    if v == float('-inf'):
        return -314159
    if v == 0.0:
        return 0
    m, e = frexp(v)
    sign = 1
    if m < 0:
        sign = -1
        m = -m
    x = 0
    while m != 0.0:
        x = ((x << 28) & MODULUS) | (x >> (61 - 28))
        m *= 268435456.0
        e -= 28
        y = int(m)  # trunc toward 0
        m -= float(y)
        x += y
        if x >= MODULUS:
            x -= MODULUS
    if e >= 0:
        e = e % 61
    else:
        e = 61 - 1 - ((-1 - e) % 61)
    x = ((x << e) & MODULUS) | (x >> (61 - e))
    h = (x if sign > 0 else -x)
    # wrapping mul? sign is +-1, x fits in 61 bits so x*sign fits i64
    if h == -1:
        h = -2
    return h

