MASK = (1<<64)-1
def ident(bits):
    x = ((bits >> 4) ^ ((bits << 20) & MASK)) & MASK
    if x >= 2**63:
        x -= 2**64
    return x >> 2

# solve (x>>4) ^ (x<<20) == target over GF(2) by brute of low bits? 
# Use gaussian elimination for each target.

def solve(target):
    # 64 vars, equation for each output bit
    # out[i] = x[i+4] if i+4<64 else 0  XOR  x[i-20] if i>=20 else 0
    # We want out == target bits
    rows = []
    for i in range(64):
        row = 0
        if i+4 < 64:
            row |= 1 << (i+4)
        if i >= 20:
            row |= 1 << (i-20)
        rhs = (target >> i) & 1
        rows.append((row, rhs))
    # gaussian
    col = 0
    where = [-1]*64
    for r in range(64):
        sel = None
        for i in range(r, 64):
            if (rows[i][0] >> r) & 1:
                sel = i
                break
        if sel is None:
            continue
        rows[r], rows[sel] = rows[sel], rows[r]
        where[r] = r
        for i in range(64):
            if i != r and (rows[i][0] >> r) & 1:
                rows[i] = (rows[i][0] ^ rows[r][0], rows[i][1] ^ rows[r][1])
    # check consistency and find free vars
