            continue
        # pivot is the lowest set bit? we pivoted on column r if it was set
        if (rows[r][0] >> r) & 1 and rows[r][1]:
            x |= 1 << r
    return x

for t in [MASK, MASK-1, MASK-2, MASK-3]:
