import os, re
root = "crates"
pat = re.compile(r"TODO|FIXME|XXX", re.IGNORECASE)
# comment extraction: line comments and block comments
line_c = re.compile(r"//.*?$", re.M)
block_c = re.compile(r"/\*.*?\*/", re.S)
hits = []
for dirpath, _, files in os.walk(root):
    for f in files:
        if not f.endswith(".rs"):
            continue
        path = os.path.join(dirpath, f)
        text = open(path, encoding="utf-8", errors="replace").read()
        # strip strings roughly so we don't count string contents that look like comments? 
        # User asked for comments. Extract comments only.
        comments = []
        for m in line_c.finditer(text):
            comments.append((m.start(), m.group()))
        for m in block_c.finditer(text):
            comments.append((m.start(), m.group()))
        for start, c in comments:
            if pat.search(c):
                line = text.count("\n", 0, start) + 1
                # show each matching line inside the comment
                base = line
                for i, cl in enumerate(c.splitlines()):
                    if pat.search(cl):
                        hits.append((path, base + i, cl.strip()))
print(f"comment hits: {len(hits)}")
for h in hits:
    print(f"{h[0]}:{h[1]}:{h[2]}")

